package com.bananalab.lite;
import java.io.*;import java.nio.file.*;import java.util.*;import javax.imageio.ImageIO;import java.awt.image.BufferedImage;import org.json.*;
public final class Stage56TrainingCheck{
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 static BananaTransformer model(Path r)throws Exception{return new BananaTransformer(Files.newInputStream(r.resolve("assets/chat34/chat34.bin")),Files.newInputStream(r.resolve("assets/chat34/vocab.txt")),Files.newInputStream(r.resolve("assets/chat34/tokenizer.json")));}
 public static void main(String[] args)throws Exception{Path r=Paths.get(args[0]);float[][] w={{.1f,-.2f},{.3f,.1f}};float[] bias={0,0};HeadTrainer.Token toy=new HeadTrainer.Token(new float[]{.5f,.8f},1);List<HeadTrainer.Token> one=Arrays.asList(toy);float epsilon=.001f;w[0][0]+=epsilon;double positive=HeadTrainer.nll(one,w,bias);w[0][0]-=2*epsilon;double negative=HeadTrainer.nll(one,w,bias);w[0][0]+=epsilon;float original=w[0][0];HeadTrainer.tokenStep(toy,null,w,bias,.001f);check(Math.abs((positive-negative)/(2*epsilon)-(original-w[0][0])/.001)<.001,"finite-difference cross entropy gradient");
 BananaTransformer chat=model(r);List<HeadTrainer.Token> train=NeuralTraining.tokens(chat,NeuralTraining.defaultRows("train")),eval=NeuralTraining.tokens(chat,NeuralTraining.defaultRows("eval")),anchors=NeuralTraining.tokens(chat,NeuralTraining.defaultRows("anchor"));float[][] old=HeadTrainer.copy(chat.head),targets=HeadTrainer.distributions(anchors,chat.head,chat.headBias);double before=HeadTrainer.nll(eval,chat.head,chat.headBias);HeadTrainer.chat(train,anchors,targets,chat.head,chat.headBias);double after=HeadTrainer.nll(eval,chat.head,chat.headBias),kl=HeadTrainer.divergence(anchors,targets,chat.head,chat.headBias),delta=HeadTrainer.distance(old,chat.head);check(after<before-1e-5&&kl<.003&&delta>0,"actual Chat weights improve local validation with bounded drift: "+before+" -> "+after+" KL "+kl);ByteArrayOutputStream bytes=new ByteArrayOutputStream();chat.save(bytes);byte[] source=Files.readAllBytes(r.resolve("assets/chat34/chat34.bin")),updated=bytes.toByteArray();check(source.length==updated.length,"same Chat binary schema");int prefix=source.length-4*(chat.d*chat.vocabSize+chat.vocabSize);check(Arrays.equals(Arrays.copyOf(source,prefix),Arrays.copyOf(updated,prefix)),"Chat body stays frozen; real output weights change");Files.write(r.resolve("test/resources/chat56-candidate.bin"),updated);
 PixelGenerator pixel=new PixelGenerator(Files.newInputStream(r.resolve("assets/pixel-v2/character21.bin")));BufferedImage image=ImageIO.read(r.resolve("assets/training/banana-own-target.png").toFile());List<HeadTrainer.Pixel> a=new ArrayList<>(),b=new ArrayList<>(),replay=new ArrayList<>();float[] condition=pixel.conditionFor(0,0xfff8d061,0,0,0);for(int y=0;y<16;y++)for(int x=0;x<16;x++){int px=x*8+3,py=y*8+3;HeadTrainer.Pixel row=new HeadTrainer.Pixel(pixel.features(pixel.coordinates(condition,px,py)),NeuralTraining.rgba(image.getRGB(px,py)));if(((x+y)&1)==0)a.add(row);else b.add(row);}float[] other=pixel.conditionFor(1,0xff629cdb,0,0,0);for(int y=0;y<8;y++)for(int x=0;x<8;x++){float[] f=pixel.features(pixel.coordinates(other,x*16+7,y*16+7)),z=HeadTrainer.logits(f,pixel.weights[3],pixel.biases[3]);for(int i=0;i<4;i++)z[i]=HeadTrainer.sigmoid(z[i]);replay.add(new HeadTrainer.Pixel(f,z));}double pb=HeadTrainer.mse(b,pixel.weights[3],pixel.biases[3]);float[][] po=HeadTrainer.copy(pixel.weights[3]);HeadTrainer.pixel(a,replay,pixel.weights[3],pixel.biases[3]);double pa=HeadTrainer.mse(b,pixel.weights[3],pixel.biases[3]),drift=HeadTrainer.mse(replay,pixel.weights[3],pixel.biases[3]);check(pa<pb-1e-7&&drift<.002&&HeadTrainer.distance(po,pixel.weights[3])>0,"actual Pixel weights improve separated pixel validation: "+pb+" -> "+pa+" drift "+drift);ByteArrayOutputStream output=new ByteArrayOutputStream();pixel.save(output);source=Files.readAllBytes(r.resolve("assets/pixel-v2/character21.bin"));updated=output.toByteArray();prefix=source.length-4*(pixel.hidden*4+4);check(source.length==updated.length&&Arrays.equals(Arrays.copyOf(source,prefix),Arrays.copyOf(updated,prefix)),"Pixel feature layers frozen and output changes");Files.write(r.resolve("test/resources/pixel56-candidate.bin"),updated);
 JSONObject report=new JSONObject().put("chatBefore",before).put("chatAfter",after).put("chatKL",kl).put("chatDelta",delta).put("pixelBefore",pb).put("pixelAfter",pa).put("pixelAnchorMSE",drift);Files.write(r.resolve("test/resources/training56-report.json"),report.toString(2).getBytes("UTF-8"));System.out.println("PASS Stage56 true neural output-layer SGD, finite-difference gradient, checkpoint schema and frozen-body checks "+report);}
}
